// Regenerates src/client-packs.generated.ts: the client subset (`toClientPack`) of every built-in pack, the only pack data
// the browser bundle carries (`@trustwork/country-packs/client`). Run after changing a file in packs/:
//   npm run generate:client -w @trustwork/country-packs
// tests/country-packs/client-entry.test.ts fails while the generated file and the pack files disagree.
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { BUILT_IN_PACKS } from '../src/registry.js';
import { toClientPack } from '../src/client.js';

const target = fileURLToPath(new URL('../src/client-packs.generated.ts', import.meta.url));
const body = JSON.stringify(BUILT_IN_PACKS.map((pack) => toClientPack(pack)), null, 2);
const source = `// Generated by packages/country-packs/bin/generate-client-packs.ts from packs/*.json: do not edit by hand.
// The client subset of the built-in country packs (no facets, sources or verification notes); see src/client.ts.
import type { ClientPack } from './client.js';

export const BUILT_IN_CLIENT_PACKS: readonly ClientPack[] = ${body};
`;
writeFileSync(target, source);
console.log(`wrote ${target} (${BUILT_IN_PACKS.length} packs, ${source.length} bytes)`);
